-- LOCAL TEST DATABASE ONLY. Subset of production tables; entitlement fixtures replace Auth.
do $$begin if not exists(select 1 from pg_roles where rolname='anon') then create role anon;end if;if not exists(select 1 from pg_roles where rolname='authenticated') then create role authenticated;end if;end $$;
create schema auth;create schema cc_internal;create schema extensions;create table auth.users(id uuid primary key);create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;create sequence public.cy_client_code_seq;create table public.cy_clients("id" uuid default gen_random_uuid() not null,"owner_id" uuid not null,"full_name" text not null,"document_number" text,"phone" text,"notes" text,"created_at" timestamptz default now() not null,"email" text,"address" text,"district" text,"address_reference" text,"alias" text,"client_code" text default ('CY-'::text || lpad((nextval('cy_client_code_seq'::regclass))::text, 6, '0'::text)));
create table public.cy_installments("id" uuid default gen_random_uuid() not null,"loan_id" uuid not null,"owner_id" uuid not null,"installment_number" int4 not null,"due_on" date not null,"amount" numeric not null,"paid_total" numeric default 0 not null,"status" text default 'PENDING'::text not null,"created_at" timestamptz default now() not null);
create table public.cy_loan_collateral("loan_id" uuid not null,"owner_id" uuid not null,"description" text not null,"created_at" timestamptz default now() not null);
create table public.cy_loan_corrections("id" uuid default gen_random_uuid() not null,"loan_id" uuid not null,"owner_id" uuid not null,"principal" numeric not null,"monthly_rate" numeric not null,"duration_months" int4 not null,"due_on" date not null,"total_due" numeric not null,"reason" text not null,"created_at" timestamptz default now() not null);
create table public.cy_loan_extensions("id" uuid default gen_random_uuid() not null,"loan_id" uuid not null,"owner_id" uuid not null,"old_due_on" date not null,"new_due_on" date not null,"old_months" int4 not null,"new_months" int4 not null,"reason" text,"created_at" timestamptz default now() not null);
create table public.cy_loans("id" uuid default gen_random_uuid() not null,"owner_id" uuid not null,"client_id" uuid not null,"principal" numeric not null,"interest_rate" numeric default 0 not null,"term_installments" int4 not null,"currency" text default 'PEN'::text not null,"issued_on" date default CURRENT_DATE not null,"first_due_on" date not null,"interval_months" int4 default 1 not null,"calculation_method" text default 'FLAT_SIMPLE'::text not null,"total_due" numeric generated always as (round((principal * ((1)::numeric + (interest_rate / (100)::numeric))), 2)) stored,"status" text default 'ACTIVE'::text not null,"created_at" timestamptz default now() not null,"duration_months" int4 default 1,"monthly_interest_rate" numeric);
create table public.cy_payments("id" uuid default gen_random_uuid() not null,"loan_id" uuid not null,"owner_id" uuid not null,"amount" numeric not null,"memo" text,"created_at" timestamptz default now() not null);
alter table public.cy_clients add primary key(id);alter table public.cy_loans add primary key(id);alter table public.cy_payments add primary key(id);alter table public.cy_installments add primary key(id);create unique index client_dni on public.cy_clients(owner_id,document_number) where document_number ~ '^[0-9]{8}$';create table cc_internal.test_access(user_id uuid primary key,active boolean not null,admin boolean not null default false);create function cc_internal.is_admin() returns boolean language sql stable as $$select coalesce((select admin from cc_internal.test_access where user_id=auth.uid()),false)$$;create function cc_internal.can_manage_cy(p_user uuid) returns boolean language sql stable as $$select p_user=auth.uid() and coalesce((select active or admin from cc_internal.test_access where user_id=p_user),false)$$;create function public.cy_subscription_status() returns table(authorized boolean,active boolean,balance_test numeric,expires_at timestamptz) language sql stable as $$select true,coalesce((select active from cc_internal.test_access where user_id=auth.uid()),false),0::numeric,now()+interval '1 day'$$;